import sys
input = sys.stdin.readline

from itertools import accumulate, permutations
from functools import lru_cache

MOD = 998244353

def get_factors(n):
    return sorted(set(reduce(list.__add__, ([i, n // i] for i in range(1, int(n ** 0.5) + 1) if n % i == 0))))

def modular_inverse(n):
    return pow(n, MOD - 2, MOD)

def read_ints():
    return [int(i) for i in input().rstrip('\n').split()]

def read_str():
    return input().rstrip('\n')

def read_single_int():
    return int(input().rstrip('\n'))

def read_chars():
    return [i for i in input().rstrip('\n')]

def read_ints_list():
    return [int(i) for i in input().rstrip('\n')]

n = read_single_int()
rock1, sci1, paper1 = read_ints()
rock2, sci2, paper2 = read_ints()

def max_score():
    return min(rock1, sci2) + min(sci1, paper2) + min(paper1, rock2)

def match_result(a, b):
    if a == b:
        return 0
    elif (a, b) in [(1, 2), (2, 3), (3, 1)]:
        return 1
    else:
        return -1

def calculate(l1, l2):
    total = 0
    c1 = c2 = 0
    while l1 or l2:
        try:
            if c1 == 0:
                c1 = l1.pop()
            if c2 == 0:
                c2 = l2.pop()
        except IndexError:
            return total
        total += max(0, min(c1[0], c2[0]) * match_result(c1[1], c2[1]))
        if c1[0] < c2[0]:
            c2 = [c2[0] - c1[0], c2[1]]
            c1 = 0
        elif c1[0] > c2[0]:
            c1 = [c1[0] - c2[0], c1[1]]
            c2 = 0
        else:
            c1 = c2 = 0
    return total

def min_score():
    permutations_list1 = [list(p) for p in permutations([[rock1, 1], [sci1, 2], [paper1, 3]])]
    permutations_list2 = [list(p) for p in permutations([[rock2, 1], [sci2, 2], [paper2, 3]])]
    min_ans = float('inf')
    for perm1 in permutations_list1:
        for perm2 in permutations_list2:
            perm1_copy = [temp[:] for temp in perm1]
            perm2_copy = [temp[:] for temp in perm2]
            min_ans = min(min_ans, calculate(perm1_copy, perm2_copy))
    return min_ans

print(min_score(), max_score())

