class MaxFlow:

    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.level = None
        self.iter = None

    def add_edge(self, u, v, cap):
        self.adj[u].append([v, cap, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def bfs(self, s):
        from collections import deque
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            v = queue.popleft()
            for to, cap, rev in self.adj[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    queue.append(to)

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.iter[v], len(self.adj[v])):
            self.iter[v] = i
            to, cap, rev = self.adj[v][i]
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    self.adj[v][i][1] -= d
                    self.adj[to][rev][1] += d
                    return d
        return 0

    def max_flow(self, s, t):
        flow = 0
        while True:
            self.bfs(s)
            if self.level[t] < 0:
                return flow
            self.iter = [0] * self.n
            while True:
                f = self.dfs(s, t, 10**9)
                if f == 0:
                    break
                flow += f

