def solve(N,k,flag):
    if k in memo[N][flag]:
        return memo[N][flag][k]
    '''
    長さNの順列
    invnum(p)-invnum(q)>kとなる場合の数
    flag=True p<qの条件あり
    flag=False p<qの条件なし
    '''
    if N==1:
        res=-1
        if flag:
            res=0
        else:
            if k<0:
